using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

// Register the model training service as a singleton
builder.Services.AddSingleton<TicketModelService>();

// Train the model at startup so the pooled engine can load it
var sp = builder.Services.BuildServiceProvider();
var modelService = sp.GetRequiredService<TicketModelService>();
modelService.TrainAndSave();

// Register the thread-safe prediction engine pool
builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>()
    .FromFile(modelService.GetModelPath());

var app = builder.Build();
app.MapControllers();
app.Run();

