arguments.new_str:
using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);

// Train the model at startup
var modelService = new TicketModelService(
    LoggerFactory.Create(b => b.AddConsole()).CreateLogger<TicketModelService>(),
    builder.Environment);
modelService.TrainAndSave();

// Register the trained model service as a singleton
builder.Services.AddSingleton(modelService);

// Register the thread-safe prediction engine pool
builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>()
    .FromFile(modelService.GetModelPath());

var app = builder.Build();

app.MapGet("/api/classifier/metrics", (TicketModelService svc) =>
{
    var metrics = svc.Metrics;
    return metrics is null ? Results.NotFound("Model has not been trained yet.") : Results.Ok(metrics);
});

app.MapPost("/api/classifier/predict", (TicketRequest request, PredictionEnginePool<TicketData, TicketPrediction> pool) =>
{
    if (string.IsNullOrWhiteSpace(request.Subject) && string.IsNullOrWhiteSpace(request.Description))
        return Results.BadRequest("Subject or Description is required.");

    if (request.Priority < 1 || request.Priority > 3)
        return Results.BadRequest("Priority must be between 1 and 3.");

    var input = new TicketData
    {
        Subject = request.Subject,
        Description = request.Description,
        Priority = request.Priority
    };

    var prediction = pool.Predict(input);

    var labels = new[] { "Billing", "General", "Technical" };
    var confidence = new Dictionary<string, float>();
    for (int i = 0; i < labels.Length && i < prediction.Score.Length; i++)
    {
        confidence[labels[i]] = prediction.Score[i];
    }

    return Results.Ok(new TicketPredictionResponse
    {
        PredictedCategory = prediction.Category,
        Confidence = confidence
    });
});

app.Run();

